 "asm/ackerman_mk8.asm": "# REF: https://en.wikipedia.org/wiki/Ackermann_function\n#  A(x,y) -> y+1             if x==0\n#            A(x-1,1)        if y==0\n#            A(x-1,A(x,y-1)) otherwise\n\nfrom=lda\nto=sta\npeek=lpa\npoke=spa\n\nx=2\ny=3\ns=4 # stack\nxx=5\nyy=6\nsb=10 # stack base\n\nlit 0 to 0\nlit 1 to 1\nin 0 to x\nin 0 to y\nlit sb to s\n\nfrom x\ninc s poke s # push\nfrom y\ninc s poke s # push\ncal ack\npeek s out 0\nhlt 0\n\nack:\n    peek s dec s # pop\n    to yy\n    peek s dec s # pop\n    to xx\n    from xx jz x_is_0\n    from yy jz y_is_0\n    otherwise: # return A(x-1,A(x,y-1))\n        from xx sub 1\n        inc s poke s # push x'\n        from xx\n        inc s poke s # push x''\n        from yy sub 1\n        inc s poke s # push y''\n        cal ack # x'' y''\n        cal ack # x' A(x'',y'')\n        ret 0\n\n    x_is_0: # return y+1\n        from yy add 1\n        inc s poke s # push result\n        ret 0\n    \n    y_is_0: # return A(x-1,1)\n        from xx sub 1\n        inc s poke s # push x'\n        lit 1\n        inc s poke s # push y'\n        cal ack\n        ret 0\n",
 "asm/ackerman_mk8_ext.asm": "# REF: https://en.wikipedia.org/wiki/Ackermann_function\n#  A(x,y) -> y+1             if x==0\n#            A(x-1,1)        if y==0\n#            A(x-1,A(x,y-1)) otherwise\n\nfrom=lda\nto=sta\npeek=lpa\npoke=spa\n\nx=2\ny=3\ns=4 # stack\nxx=5\nyy=6\nsb=10 # stack base\n\nlit 0 to 0\nlit 1 to 1\nin 0 to x\nin 0 to y\nlit sb to s\n\nfrom x push s\nfrom y push s\ncal ack\npeek s out 0\nhlt 0\n\nack:\n    pop s to yy\n    pop s to xx\n    from xx jz x_is_0\n    from yy jz y_is_0\n    otherwise: # return A(x-1,A(x,y-1))\n        from xx sub 1 push s # x'\n        from xx       push s # x''\n        from yy sub 1 push s # y''\n        cal ack # x'' y''\n        cal ack # x' A(x'',y'')\n        ret 0\n\n    x_is_0: # return y+1\n        from yy add 1 push s\n        ret 0\n    \n    y_is_0: # return A(x-1,1)\n        from xx sub 1 push s # push x'\n        lit 1 push s # push y'\n        cal ack\n        ret 0\n",
